package tn.esprit.partnerintelligence.entity;
import jakarta.persistence.*;import java.time.Instant;@Entity public class DealHealthScoreSnapshot { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long partnerId; private Long dealId; private Double healthScore; private Double confidence; @Column(length=1000) private String factors; private Instant createdAt=Instant.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getPartnerId(){return partnerId;} public void setPartnerId(Long partnerId){this.partnerId=partnerId;} public Long getDealId(){return dealId;} public void setDealId(Long dealId){this.dealId=dealId;} public Double getHealthScore(){return healthScore;} public void setHealthScore(Double healthScore){this.healthScore=healthScore;} public Double getConfidence(){return confidence;} public void setConfidence(Double confidence){this.confidence=confidence;} public String getFactors(){return factors;} public void setFactors(String factors){this.factors=factors;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant createdAt){this.createdAt=createdAt;} }